    /* Preferred representative per model, in priority order. */
    /* Palette tiles show the colour symbol: it keeps its silhouette at 64px,
       where a wordmark collapses into a grey smear. */
    var PREFER_LIGHT = ['symbol-color', 'symbol-brand-color', 'symbol-black', 'symbol-brand-black', 'symbol-white', 'symbol-brand-white', 'tile-light'];
    var PREFER_DARK = ['symbol-color-dark', 'symbol-brand-color-dark', 'symbol-white', 'symbol-brand-white', 'tile-dark', 'symbol-color', 'symbol-black'];

    /**
     * Models whose wordmark reads better than their symbol.
     *
     * Only these two were asked for: their marks are wide text banners that
     * look like a placeholder at tile size, while the name is the point.
     */
    var WORDMARK_MODELS = {
      DALLE: true,
      StableDiffusion: true,
      FLUX: true,
      Runway: true,
      MiMo: true,
      Gemma: true
    };

    /**
     * Pick a representative icon id for a model.
     *
     * @param {string} model  model name
     * @param {boolean} dark  pick for a dark backdrop
     */
    function pickIcon(model, dark) {
      var list = ICON_GROUPS[model];
      if (!list || !list.length) return null;

      /* A couple of models read better as a wordmark even at tile size. */
      if (!dark && typeof WORDMARK_MODELS !== 'undefined' && WORDMARK_MODELS[model]) {
        for (var w = 0; w < list.length; w++) {
          if (list[w].variant === 'wordmark-black') return list[w].id;
        }
      }

      var pri = dark ? PREFER_DARK : PREFER_LIGHT;
      for (var i = 0; i < pri.length; i++) {
        for (var j = 0; j < list.length; j++) {
          if (list[j].variant === pri[i]) return list[j].id;
        }
      }
      return list[0].id;
    }

